from pathlib import Path


def replace_once(path: Path, old: str, new: str, label: str) -> None:
    text = path.read_text(encoding="utf-8")
    if text.count(old) != 1:
        raise SystemExit(f"{label}: expected exactly one anchor, found {text.count(old)}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")


# Desktop persistence: use one SQLite statement for put-if-empty and one
# compare-and-clear statement. Separate DesktopChatDb connections therefore
# serialize through SQLite instead of a read-then-upsert race.
db_path = Path("desktop/composeApp/src/main/kotlin/dk/ternedal/modelrig/desktop/data/DesktopChatDb.kt")
old = '''    fun putSetting(key: String, value: String) {\n        val stored = if (key in CREDENTIAL_SETTING_KEYS && value.isNotEmpty()) {\n            protectCredential(value)\n        } else {\n            value\n        }\n        putRawSetting(storageKey(key), stored)\n    }\n\n    private fun storageKey(key: String): String {\n'''
new = '''    fun putSetting(key: String, value: String) {\n        val stored = if (key in CREDENTIAL_SETTING_KEYS && value.isNotEmpty()) {\n            protectCredential(value)\n        } else {\n            value\n        }\n        putRawSetting(storageKey(key), stored)\n    }\n\n    /** Atomically reserve an unprotected setting only while its slot is empty. */\n    internal fun reserveSettingIfEmpty(key: String, value: String): Boolean {\n        require(key !in CREDENTIAL_SETTING_KEYS) { "credential settings require protected writes" }\n        require(value.isNotEmpty()) { "reserved setting value must be non-empty" }\n        val resolvedKey = storageKey(key)\n        return synchronized(conn) {\n            conn.prepareStatement(\n                "INSERT INTO setting(key, value) VALUES(?, ?) " +\n                    "ON CONFLICT(key) DO UPDATE SET value = excluded.value WHERE setting.value = ''",\n            ).use { st ->\n                st.setString(1, resolvedKey)\n                st.setString(2, value)\n                st.executeUpdate() == 1\n            }\n        }\n    }\n\n    /** Clear only the exact unprotected setting authority that this caller owns. */\n    internal fun clearSettingIfEquals(key: String, expectedValue: String): Boolean {\n        require(key !in CREDENTIAL_SETTING_KEYS) { "credential settings require protected writes" }\n        require(expectedValue.isNotEmpty()) { "expected setting value must be non-empty" }\n        val resolvedKey = storageKey(key)\n        return synchronized(conn) {\n            conn.prepareStatement(\n                "UPDATE setting SET value = '' WHERE key = ? AND value = ?",\n            ).use { st ->\n                st.setString(1, resolvedKey)\n                st.setString(2, expectedValue)\n                st.executeUpdate() == 1\n            }\n        }\n    }\n\n    private fun storageKey(key: String): String {\n'''
replace_once(db_path, old, new, "DesktopChatDb atomic setting helpers")

# Desktop recovery-store API exposes only authority-safe reservation/clearing.
desktop_store = Path("desktop/composeApp/src/main/kotlin/dk/ternedal/modelrig/desktop/data/Agent3ReviewedStartRecoveryStore.kt")
desktop_store.write_text('''package dk.ternedal.modelrig.desktop.data\n\n/** Separate URL-scoped persistence for reviewed Start; task-surface authority is never reused. */\nclass Agent3ReviewedStartRecoveryStore(private val db: DesktopChatDb) {\n    fun read(baseUrl: String?): String? = agent3ReviewedStartRecoveryStorageKey(baseUrl)\n        ?.let(db::getSetting)\n        ?.trim()\n        ?.takeIf { it.isNotEmpty() }\n\n    /** Acquire the rig slot without replacing another process' unresolved Start authority. */\n    fun reserve(baseUrl: String?, encodedAuthority: String?): Boolean {\n        val key = agent3ReviewedStartRecoveryStorageKey(baseUrl) ?: return false\n        val normalized = encodedAuthority?.trim()?.takeIf { it.isNotEmpty() } ?: return false\n        return runCatching { db.reserveSettingIfEmpty(key, normalized) }.getOrDefault(false)\n    }\n\n    /** Clear only if the slot still contains this exact originating authority. */\n    fun clearIfMatches(baseUrl: String?, encodedAuthority: String?): Boolean {\n        val key = agent3ReviewedStartRecoveryStorageKey(baseUrl) ?: return false\n        val normalized = encodedAuthority?.trim()?.takeIf { it.isNotEmpty() } ?: return false\n        return runCatching { db.clearSettingIfEquals(key, normalized) }.getOrDefault(false)\n    }\n}\n\ninternal fun agent3ReviewedStartRecoveryStorageKey(baseUrl: String?): String? =\n    baseUrl\n        ?.trim()\n        ?.trimEnd('/')\n        ?.takeIf { it.isNotEmpty() }\n        ?.let { "$REVIEWED_START_RECOVERY_KEY_PREFIX:$it" }\n\nprivate const val REVIEWED_START_RECOVERY_KEY_PREFIX = "agent3ReviewedStartRecovery"\n''', encoding="utf-8")

# Android SharedPreferences is process-local; serialize screen instances through
# one lock and use the same exact-authority semantics. Android multi-process
# SharedPreferences is not an authority model used by this app.
android_store = Path("android/app/src/main/java/dk/ternedal/modelrig/data/Agent3ReviewedStartRecoveryStore.kt")
android_store.write_text('''package dk.ternedal.modelrig.data\n\nimport android.content.Context\n\n/** URL-scoped storage for the opaque reviewed-Start recovery authority record. */\nclass Agent3ReviewedStartRecoveryStore(context: Context) {\n    private val prefs = context.getSharedPreferences("modelrig", Context.MODE_PRIVATE)\n\n    fun read(baseUrl: String?): String? = agent3ReviewedStartRecoveryStorageKey(baseUrl)\n        ?.let { prefs.getString(it, null) }\n        ?.trim()\n        ?.takeIf { it.isNotEmpty() }\n\n    /** Acquire the rig slot without replacing another screen's unresolved Start authority. */\n    fun reserve(baseUrl: String?, encodedAuthority: String?): Boolean {\n        val key = agent3ReviewedStartRecoveryStorageKey(baseUrl) ?: return false\n        val normalized = encodedAuthority?.trim()?.takeIf { it.isNotEmpty() } ?: return false\n        return synchronized(SLOT_LOCK) {\n            val current = prefs.getString(key, null)?.trim()?.takeIf { it.isNotEmpty() }\n            if (current != null) false else prefs.edit().putString(key, normalized).commit()\n        }\n    }\n\n    /** Clear only if this screen still owns the exact authority stored in the rig slot. */\n    fun clearIfMatches(baseUrl: String?, encodedAuthority: String?): Boolean {\n        val key = agent3ReviewedStartRecoveryStorageKey(baseUrl) ?: return false\n        val normalized = encodedAuthority?.trim()?.takeIf { it.isNotEmpty() } ?: return false\n        return synchronized(SLOT_LOCK) {\n            val current = prefs.getString(key, null)?.trim()?.takeIf { it.isNotEmpty() }\n            if (current != normalized) false else prefs.edit().remove(key).commit()\n        }\n    }\n\n    private companion object {\n        val SLOT_LOCK = Any()\n    }\n}\n\ninternal fun agent3ReviewedStartRecoveryStorageKey(baseUrl: String?): String? =\n    baseUrl\n        ?.trim()\n        ?.trimEnd('/')\n        ?.takeIf { it.isNotEmpty() }\n        ?.let { "$REVIEWED_START_RECOVERY_KEY_PREFIX:$it" }\n\nprivate const val REVIEWED_START_RECOVERY_KEY_PREFIX = "agent3_reviewed_start_recovery"\n''', encoding="utf-8")

# Desktop UI: reserve before network I/O; completion/refusal may clear only its
# own authority. A failed conditional clear stays fail-closed and reloads the
# slot for presentation rather than pretending it was cleared.
desktop_app = Path("desktop/composeApp/src/main/kotlin/dk/ternedal/modelrig/desktop/Agent3ReviewDevApp.kt")
old = '''            val cleared = recoveryStore.write(connection.baseUrl, null)\n            if (!Agent3DevInteractionPolicy.canPublishForConnection(connection, currentConnectionOrNull())) {\n                return\n            }\n            run = envelope.run\n            review = envelope.readReview\n            if (cleared) {\n                pendingStartRecovery = null\n                startRecoveryUnresolved = false\n            } else {\n                pendingStartRecovery = authority\n                startRecoveryUnresolved = true\n                error = "Run blev valideret, men den lokale Start-recovery kunne ikke ryddes. Samme plan kan sikkert gendannes igen."\n            }\n'''
new = '''            val cleared = recoveryStore.clearIfMatches(connection.baseUrl, authority.encode())\n            if (!Agent3DevInteractionPolicy.canPublishForConnection(connection, currentConnectionOrNull())) {\n                return\n            }\n            run = envelope.run\n            review = envelope.readReview\n            if (cleared) {\n                pendingStartRecovery = null\n                startRecoveryUnresolved = false\n            } else {\n                val currentRaw = recoveryStore.read(connection.baseUrl)\n                pendingStartRecovery = Agent3ReviewedStartRecoveryAuthority.decode(currentRaw)\n                startRecoveryUnresolved = true\n                error = "Run blev valideret, men recovery-slotten kunne ikke ryddes som den samme authority. Nye Starts forbliver blokeret."\n            }\n'''
replace_once(desktop_app, old, new, "desktop success conditional clear")
