# Desktop regression: two independent JDBC connections model separate desktop
# processes sharing ~/.modelrig/modelrig.db. The second authority cannot replace
# or clear the first one.
desktop_test = Path("desktop/composeApp/src/test/kotlin/dk/ternedal/modelrig/desktop/data/Agent3ReviewedStartRecoveryStoreTest.kt")
desktop_test.write_text('''package dk.ternedal.modelrig.desktop.data\n\nimport java.nio.file.Files\nimport kotlin.io.path.deleteIfExists\nimport kotlin.test.Test\nimport kotlin.test.assertEquals\nimport kotlin.test.assertFalse\nimport kotlin.test.assertNotEquals\nimport kotlin.test.assertNull\nimport kotlin.test.assertTrue\n\nclass Agent3ReviewedStartRecoveryStoreTest {\n    @Test\n    fun reviewedRecoveryKeyIsNormalizedAndRigScoped() {\n        assertEquals(\n            agent3ReviewedStartRecoveryStorageKey(" https://rig.example/ "),\n            agent3ReviewedStartRecoveryStorageKey("https://rig.example"),\n        )\n        assertNotEquals(\n            agent3ReviewedStartRecoveryStorageKey("https://rig-a.example"),\n            agent3ReviewedStartRecoveryStorageKey("https://rig-b.example"),\n        )\n        assertNull(agent3ReviewedStartRecoveryStorageKey("  "))\n    }\n\n    @Test\n    fun reviewedRecoverySlotIsAtomicAcrossIndependentDatabaseConnections() {\n        val path = Files.createTempFile("modelrig-reviewed-start-slot-", ".db")\n        try {\n            DesktopChatDb(path.toString()).use { dbA ->\n                DesktopChatDb(path.toString()).use { dbB ->\n                    val storeA = Agent3ReviewedStartRecoveryStore(dbA)\n                    val storeB = Agent3ReviewedStartRecoveryStore(dbB)\n                    val url = "https://rig.example"\n                    val authorityA = "authority-a"\n                    val authorityB = "authority-b"\n\n                    assertTrue(storeA.reserve(url, authorityA))\n                    assertFalse(storeB.reserve(url, authorityB))\n                    assertEquals(authorityA, storeB.read(url))\n\n                    assertFalse(storeB.clearIfMatches(url, authorityB))\n                    assertEquals(authorityA, storeA.read(url))\n                    assertTrue(storeA.clearIfMatches(url, authorityA))\n                    assertNull(storeB.read(url))\n\n                    assertTrue(storeB.reserve(url, authorityB))\n                    assertEquals(authorityB, storeA.read(url))\n                }\n            }\n        } finally {\n            path.deleteIfExists()\n        }\n    }\n}\n''', encoding="utf-8")

# Android regression uses two store instances backed by the same SharedPreferences
# file, matching concurrent screen instances in one app process.
android_test = Path("android/app/src/test/java/dk/ternedal/modelrig/data/Agent3ReviewedStartRecoveryStoreTest.kt")
android_test.write_text('''package dk.ternedal.modelrig.data\n\nimport android.content.Context\nimport org.junit.Assert.assertEquals\nimport org.junit.Assert.assertFalse\nimport org.junit.Assert.assertNotEquals\nimport org.junit.Assert.assertNull\nimport org.junit.Assert.assertTrue\nimport org.junit.Test\nimport org.junit.runner.RunWith\nimport org.robolectric.RobolectricTestRunner\nimport org.robolectric.RuntimeEnvironment\n\n@RunWith(RobolectricTestRunner::class)\nclass Agent3ReviewedStartRecoveryStoreTest {\n    @Test\n    fun `reviewed recovery key is normalized and rig scoped`() {\n        assertEquals(\n            agent3ReviewedStartRecoveryStorageKey(" https://rig.example/ "),\n            agent3ReviewedStartRecoveryStorageKey("https://rig.example"),\n        )\n        assertNotEquals(\n            agent3ReviewedStartRecoveryStorageKey("https://rig-a.example"),\n            agent3ReviewedStartRecoveryStorageKey("https://rig-b.example"),\n        )\n        assertNull(agent3ReviewedStartRecoveryStorageKey("  "))\n    }\n\n    @Test\n    fun `reviewed recovery slot is reserved and cleared only by exact authority`() {\n        val context = RuntimeEnvironment.getApplication()\n        context.getSharedPreferences("modelrig", Context.MODE_PRIVATE).edit().clear().commit()\n        val storeA = Agent3ReviewedStartRecoveryStore(context)\n        val storeB = Agent3ReviewedStartRecoveryStore(context)\n        val url = "https://rig.example"\n\n        assertTrue(storeA.reserve(url, "authority-a"))\n        assertFalse(storeB.reserve(url, "authority-b"))\n        assertEquals("authority-a", storeB.read(url))\n        assertFalse(storeB.clearIfMatches(url, "authority-b"))\n        assertEquals("authority-a", storeA.read(url))\n        assertTrue(storeA.clearIfMatches(url, "authority-a"))\n        assertNull(storeB.read(url))\n        assertTrue(storeB.reserve(url, "authority-b"))\n    }\n}\n''', encoding="utf-8")

